//! feature `tauri` のときだけ、Tauri の plugin の permission（`permissions/autogenerated/`・`permissions/schemas/`）を生成する。
//! コマンドの一覧は `src/tauri.rs` の `generate_handler!` と同じ並び。生成物は commit し、CI が差分の無いことを確かめる。

fn main() {
  println!("cargo:rerun-if-changed=build.rs");
  #[cfg(feature = "tauri")]
  tauri_plugin::Builder::new(COMMANDS).build();
}

#[cfg(feature = "tauri")]
const COMMANDS: &[&str] = &[
  "account_state",
  "account_begin_login",
  "account_cancel_login",
  "account_logout",
  "account_open_my_page",
];
